head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataMap > M > getRefComponent]<br/>ref 속성으로 DataMap 모듈과 바인드 된 컴포넌트의 ID 정보를 배열로 반환합니다.",
    "validation" : [
        "반환값으로 ref 속성으로 DataMap 모듈과 바인드 된 컴포넌트의 ID 정보를 객체 배열로 반환합니다.",
        "바인드 된 컴포넌트당 하나의 객체가 반환되며 바인드 된 컴포넌트가 없는 경우 빈 배열이 반환됩니다.",
        "ref.originalID 속성값으로 바인드 된 컴포넌트의 디자인 ID 값을 갖습니다.",
        "ref.id 속성값으로 바인드 된 컴포넌트의 렌더링 ID 값을 갖습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof input1 !== 'undefined') {
        input1.remove();
    }    

    if (typeof anchor1 !== 'undefined') {
        anchor1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };    

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);      

    // target 생성
    $c.gcm.createBasicDataMap();
    $c.gcm.createBasicDataMap('', '', 'target2');

    // input 생성
    $c.gcm.createEmptyInput('ref="data:target1.key1" style="width:200px;"', '', 'input1');

    // anchor 생성
    $c.gcm.createBasicAnchor('ref="data:target1.key1"', '', 'anchor1');

    scwin.btn_getRefComponent_onclick();
}   



scwin.btn_getRefComponent_onclick = function (e) {
    let rtn = target1.getRefComponent();    

    wf_body_bottom.getObj("scwin").setReturnValue("target1 result: " + rtn);

    for (var i=0; i<rtn.length; i++) {
        wf_body_bottom.getObj("scwin").setReturnValue("target1 result["+i+"].originalID: " + rtn[i].originalID);	
        wf_body_bottom.getObj("scwin").setReturnValue("target1 result["+i+"].id: " + rtn[i].id);	
    }        

    rtn = target2.getRefComponent();
    wf_body_bottom.getObj("scwin").setReturnValue("target2 result: " + rtn);
};
